  parseTextToCss: function parseTextToCss(text) {
    var css = '';
    var imports = _toConsumableArray(text.matchAll(/@import[^;]*;/gi));
    for (var imp in imports) {
      css += imports[imp];
      text = text.replace(imports[imp], '');
    }
    jQuery.parsecss(text, function (e) {
      jQuery('#acym__wysid__custom__style').remove();
      css += acym_helperEditorWysid.parsecssP(e);
      var medias = _toConsumableArray(text.matchAll(/@media[^{(]*(\([^{]*\))[^{]*{([^{}]*({[^}]*}[^{}]*)*[^{}]*)}/gi));
      for (var media in medias) {
        if (medias[media][2] === undefined) {
          continue;
        }
        css += '@media' + medias[media][1] + '{';
        jQuery.parsecss(medias[media][2], function (ecss) {
          css += acym_helperEditorWysid.parsecssP(ecss);
        });
        css += '}';
      }
    });
    return css;
  },
  parsecssP: function parsecssP(e) {
    var css = '';
    var stylesheetToApply = e;
    for (var key in stylesheetToApply) {
      var allCss = stylesheetToApply[key];
      var prependClass = key.indexOf('#acym__wysid__template') !== -1 ? '' : '#acym__wysid__template .body ';
      css += prependClass + key + '{';
      for (var keyCss in allCss) {
        css += keyCss + ':' + allCss[keyCss] + ';';
      }
      css += '} ';
    }
    return css;
  },
